do $$ declare binding jsonb:='{"platform":"ios","bundle":"com.dbakp.taskfold","environment":"development","token":"c070","time_zone":"America/New_York","permission":"authorized","enabled":false}'; at timestamp:=timezone('UTC',date_trunc('minute',clock_timestamp())+interval '1 minute'); begin
 perform public.taskfold_register_reminder_device('f0701000-0000-4000-8000-000000000003',repeat('a',64),1,binding);
 perform public.taskfold_register_reminder_device('f0701000-0000-4000-8000-000000000003',repeat('a',64),2,binding||'{"enabled":true}');
 insert into public.tasks(id,user_id,title,reminder_specs) values('f0701000-0000-4000-8000-000000000004',auth.uid(),'Calendar queue fixture',jsonb_build_array(jsonb_build_object('version',2,'id','f0701000-0000-4000-8000-000000000005','kind','recurring','enabled',true,'channels',jsonb_build_array('local'),'start_day',to_char(at,'YYYY-MM-DD'),'time',to_char(at,'HH24:MI'),'time_zone','Etc/UTC','recurrence',jsonb_build_object('type','daily','count',3))));
 begin perform taskfold_private.reminder_events_window('{}','UTC',now(),now()); raise exception 'Client projected service calendar'; exception when insufficient_privilege then null; end;
end $$;
reset role;
set local role service_role;
do $$ declare device uuid:='f0701000-0000-4000-8000-000000000003'; fixture_task uuid:='f0701000-0000-4000-8000-000000000004'; job jsonb; payload jsonb; e jsonb; millis text; queued jsonb; delay double precision; begin
 queued:=public.taskfold_reconcile_reminder_jobs(device); if queued->>'queued'<>'3' then raise exception 'Calendar queue lost original or future occurrences: %',queued; end if;
 if public.taskfold_reconcile_reminder_jobs(device)->>'queued'<>'0' then raise exception 'Reconcile duplicated calendar'; end if;
 select greatest(0,extract(epoch from min(fire_at)-clock_timestamp())+0.1) into delay from taskfold_private.reminder_jobs where device_id=device;
 if delay>60 then raise exception 'Unbounded fixture clock wait'; end if; perform pg_sleep(delay);
 job:=public.taskfold_claim_reminder_jobs(device,1)->0; if job is null or job->>'signature' not like 'r5:%' then raise exception 'Calendar due occurrence not claimed'; end if;
 payload:=public.taskfold_prepare_reminder_job(job->>'id',(job->>'lease')::uuid); e:=payload->'content'->'info'; millis:=round((e->>'originalAt')::numeric*1000)::bigint::text;
 if payload is null or e->'calendarOccurrence'<>'true'::jsonb or e->>'eventID'<>fixture_task::text||'.f0701000-0000-4000-8000-000000000005.'||millis or e->>'signature'<>job->>'signature' then raise exception 'Calendar provider identity drifted'; end if;
 if public.taskfold_claim_reminder_jobs(device,1)<>'[]'::jsonb then raise exception 'Calendar lease claimed twice'; end if;
 if not public.taskfold_finish_reminder_delivery(job->>'id',(job->>'lease')::uuid,'accepted',null) then raise exception 'Calendar acceptance lost'; end if;
 if public.taskfold_reconcile_reminder_jobs(device)->>'queued'<>'0' or public.taskfold_claim_reminder_jobs(device,1)<>'[]'::jsonb then raise exception 'Accepted calendar occurrence resent'; end if;
 -- Current membership rechecks the historical original, even if it is no longer future.
 update taskfold_private.reminder_jobs set state='leased',lease_token=gen_random_uuid(),lease_until=clock_timestamp()+interval '30 seconds' where id=job->>'id';
 select jsonb_build_object('id',j.id,'lease',j.lease_token) into job from taskfold_private.reminder_jobs j where id=job->>'id';
 update public.tasks set reminder_specs=jsonb_set(reminder_specs,'{0,recurrence,count}','2') where id=fixture_task;
 if public.taskfold_prepare_reminder_job(job->>'id',(job->>'lease')::uuid) is not null or public.taskfold_finish_reminder_delivery(job->>'id',(job->>'lease')::uuid,'accepted',null) then raise exception 'Changed calendar rule retained held lease'; end if;
 if public.taskfold_reconcile_reminder_jobs(device)->>'queued'<>'1' then raise exception 'Rule edit replayed past original or lost future occurrence'; end if;
 update public.tasks set completed=true where id=fixture_task;
 if exists(select 1 from taskfold_private.reminder_jobs j where j.task_id=fixture_task and state in ('pending','leased')) then raise exception 'Completed calendar retained pending delivery'; end if;
end $$;
reset role;
do $$ declare name text; begin
 foreach name in array array['taskfold_private.reminder_calendar_wall_time(timestamp without time zone,text)','taskfold_private.reminder_calendar_dates_validated(jsonb,timestamp with time zone,timestamp with time zone)','taskfold_private.reminder_month_day(integer,integer,jsonb,integer)','taskfold_private.reminder_calendar_next(jsonb,date,date)','taskfold_private.reminder_spec_valid(jsonb)','taskfold_private.reminder_calendar_dates(jsonb,timestamp with time zone,timestamp with time zone)','taskfold_private.reminder_events_window(jsonb,text,timestamp with time zone,timestamp with time zone)'] loop
  if has_function_privilege('anon',name,'execute') or has_function_privilege('authenticated',name,'execute') or not has_function_privilege('service_role',name,'execute') then raise exception 'Calendar projection privilege boundary incorrect'; end if;
 end loop;
 if exists(select 1 from cron.job where jobname='taskfold-native-reminder-sweep' and active) then raise exception 'Native dispatch was activated'; end if;
end $$;
